{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Encainide had an absolute oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Flavoxate had an absolute oral bioavailability close to 100% in healthy male volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Mizolastine had an absolute oral bioavailability of 65% after a single 10 mg tablet in healthy young volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer numeric absolute bioavailability records in healthy subjects consistently exceed 20% (32%, ~100%, 65%), and no affirmative numeric low-F record was supplied; therefore predict high.",
  "evidence_gaps": [
    "Qualitative records such as 'good bioavailability' for macimorelin and 'not good' for ilomastat lack numeric threshold specificity and were not used as decisive evidence.",
    "Encainide's reported bioavailability range (7–82%) includes values below 20%, but its absolute normal-subject value is 32 ± 7%.",
    "Nabumetone's absolute bioavailability was measured for its active metabolite, reducing directness for the parent endpoint."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

